class LiveLogger{static initialized=!1;static listbox=null;static init(){LiveLogger.initialized||(LiveLogger.initialized=!0,window.live_logger={log(e,o){if(null!=LiveLogger.listbox)switch(o){case"warn":LiveLogger.listbox.addItem(e,{color:"var(--vscode-editorWarning-foreground)"});break;case"danger":LiveLogger.listbox.addItem(e,{color:"var(--vscode-errorForeground)"});break;case"success":LiveLogger.listbox.addItem(e,{color:"var(--vscode-charts-green)"});break;case"info":LiveLogger.listbox.addItem(e,{color:"var(--vscode-editorInfo-foreground)"});break;case"none":default:LiveLogger.listbox.addItem(e);break}else switch(o){case"warn":console.warn(`BE:${e}`);break;case"danger":console.error(`BE:${e}`);break;case"success":console.log(`BE✓:${e}`);break;default:console.log(`BE:${e}`);break}}})}static log(e,o){window.live_logger.log(e,o)}}LiveLogger.init();